 "content": "from collections import Counter, defaultdict


def transform(grid):
    """Restore masked cells in a framed, diagonally periodic color field."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Learn the diagonal color cycle from the unmasked interior. The small
    # upper-left corner is a seed region; regular diagonals begin at r+c >= 9.
    diagonals = defaultdict(Counter)
    for r in range(3, h):
        for c in range(3, w):
            if r + c >= 9 and grid[r][c] != 0:
                diagonals[r + c][grid[r][c]] += 1
    diag_color = {s: counts.most_common(1)[0][0] for s, counts in diagonals.items()}
    if not diag_color:
        raise ValueError("Cannot infer diagonal pattern from visible cells")

    period = None
    for p in range(1, min(15, h + w) + 1):
        by_residue = {}
        valid = True
        for s, color in diag_color.items():
            residue = s % p
            if residue in by_residue and by_residue[residue] != color:
                valid = False
                break
            by_residue[residue] = color
        if valid:
            period = p
            break
    if period is None:
        raise ValueError("No repeating diagonal color cycle found")
    cycle = {s % period: color for s, color in diag_color.items()}

    for r in range(h):
        for c in range(w):
            if out[r][c] != 0:
                continue
            if r < 2 or c < 2:
                out[r][c] = 1
            elif r == 2 or c == 2:
                out[r][c] = 4
            else:
                s = r + c
                if s % period in cycle:
                    out[r][c] = cycle[s % period]
                else:
                    # Only needed if a whole diagonal residue is occluded;
                    # use the nearest observed diagonal with the same phase.
                    candidates = [(abs(t - s), color) for t, color in diag_color.items()
                                  if t % period == s % period]
                    if not candidates:
                        raise ValueError("Cannot infer masked diagonal")
                    out[r][c] = min(candidates)[1]
    return out
